// Ported from Limbophobia src/world/remains/corpse.ts (same author): its texture painters only; the geometry and game code stay there.
// Generated by the material library's extractor and then kept by hand. Paints at 32 px per metre (src/gfx/mat/atlas.ts).
import { addTextureModule } from '../../../textures/index';
import { atlas } from '../../../atlas';

const SLOTS = 3, PX = 128;
export const unitTex = (v: number) => 'rm_unit_page_' + (((v % SLOTS) + SLOTS) % SLOTS);
addTextureModule(() => { const A = atlas(); for (let i = 0; i < SLOTS; i++) A.add(unitTex(i), PX, PX, (pc) => { pc.wrap = false; pc.fill(0xc8a050); }); });
